1	package upgrade
2	
3	import (
4		"context"
5		"debug/buildinfo"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"runtime/debug"
11		"strings"
12	)
13	
14	type Method string
15	
16	const (
17		MethodHomebrew Method = "homebrew"
18		MethodCurl     Method = "curl"
19		MethodGo       Method = "go"
20	)
21	
22	type Installation struct {
23		Method       Method
24		BinaryPath   string
25		ResolvedPath string
26		BrewCask     string
27		Version      Version
28	}
29	
30	type Environment struct {
31		Home       string
32		BrewPrefix string
33		GoBin      string
34		GoPath     string
35	}
36	
37	func DetectInstallation(ctx context.Context) (Installation, error) {
38		binaryPath, err := exec.LookPath("entire")
39		if err != nil {
40			return Installation{}, fmt.Errorf("entire CLI not found on PATH: %w", err)
41		}
42	
43		resolvedPath, err := filepath.EvalSymlinks(binaryPath)
44		if err != nil {
45			resolvedPath = binaryPath
46		}
47	
48		home, _ := os.UserHomeDir()
49		env := Environment{
50			Home:       home,
51			BrewPrefix: commandOutput(ctx, "brew", "--prefix"),
52			GoBin:      commandOutput(ctx, "go", "env", "GOBIN"),
53			GoPath:     commandOutput(ctx, "go", "env", "GOPATH"),
54		}
55	
56		install, ok := ClassifyInstallation(binaryPath, resolvedPath, env)
57		if !ok {
58			return Installation{}, fmt.Errorf("unsupported Entire CLI installation at %s; supported update methods are Homebrew, install.sh, and go install", binaryPath)
59		}
60	
61		versionOut, err := exec.CommandContext(ctx, binaryPath, "--version").CombinedOutput()
62		if err != nil {
63			return Installation{}, versionCommandError(err, versionOut)
64		}
65		version, err := ParseVersion(string(versionOut))
66		if err != nil {
67			if install.Method != MethodGo {
68				return Installation{}, err
69			}
70			parseErr := err
71			version, err = versionFromGoBuildInfo(resolvedPath)
72			if err != nil {
73				return Installation{}, fmt.Errorf("%w; Go build info fallback failed: %v", parseErr, err)
74			}
75		}
76		install.Version = version
77		return install, nil
78	}
79	
80	func versionFromGoBuildInfo(binaryPath string) (Version, error) {
81		info, err := buildinfo.ReadFile(binaryPath)
82		if err != nil {
83			return Version{}, fmt.Errorf("read Go build info from %s: %w", binaryPath, err)
84		}
85		return versionFromBuildInfo(info)
86	}
87	
88	func versionFromBuildInfo(info *debug.BuildInfo) (Version, error) {
89		if info == nil {
90			return Version{}, fmt.Errorf("missing Go build info")
91		}
92	
93		candidates := []string{}
94		if isEntireCLIModulePath(info.Main.Path) {
95			candidates = append(candidates, info.Main.Version)
96		}
97		for _, dep := range info.Deps {
98			if dep != nil && isEntireCLIModulePath(dep.Path) {
99				candidates = append(candidates, dep.Version)
100			}
101		}
102	
103		for _, candidate := range candidates {
104			if candidate == "" || candidate == "(devel)" {
105				continue
106			}
107			if version, err := ParseVersion(candidate); err == nil {
108				return version, nil
109			}
110		}
111		return Version{}, fmt.Errorf("Go build info did not include an Entire CLI module version")
112	}
113	
114	func isEntireCLIModulePath(path string) bool {
115		return path == "github.com/entireio/cli" || strings.HasPrefix(path, "github.com/entireio/cli/")
116	}
117	
118	func versionCommandError(err error, output []byte) error {
119		message := strings.TrimSpace(string(output))
120		if message == "" {
121			return fmt.Errorf("failed to read installed Entire CLI version: %w", err)
122		}
123		return fmt.Errorf("failed to read installed Entire CLI version: %w: %s", err, message)
124	}
125	
126	func ClassifyInstallation(binaryPath, resolvedPath string, env Environment) (Installation, bool) {
127		binaryPath = filepath.Clean(binaryPath)
128		resolvedPath = filepath.Clean(resolvedPath)
129	
130		install := Installation{
131			BinaryPath:   binaryPath,
132			ResolvedPath: resolvedPath,
133		}
134	
135		if cask, ok := brewCaskForPath(resolvedPath, env.BrewPrefix); ok {
136			install.Method = MethodHomebrew
137			install.BrewCask = cask
138			return install, true
139		}
140	
141		for _, dir := range goBinDirs(env) {
142			goPath := filepath.Join(dir, executableName("entire"))
143			if samePath(binaryPath, goPath) || samePath(resolvedPath, goPath) {
144				install.Method = MethodGo
145				return install, true
146			}
147		}
148	
149		if env.Home != "" {
150			curlPath := filepath.Join(env.Home, ".local", "bin", executableName("entire"))
151			if samePath(binaryPath, curlPath) || samePath(resolvedPath, curlPath) {
152				install.Method = MethodCurl
153				return install, true
154			}
155		}
156	
157		return Installation{}, false
158	}
159	
160	func brewCaskForPath(path, brewPrefix string) (string, bool) {
161		type candidate struct {
162			dir  string
163			cask string
164		}
165		candidates := []candidate{}
166		if brewPrefix != "" {
167			candidates = append(candidates,
168				candidate{dir: filepath.Join(brewPrefix, "Caskroom", "entire@nightly"), cask: "entire@nightly"},
169				candidate{dir: filepath.Join(brewPrefix, "Caskroom", "entire"), cask: "entire"},
170			)
171		}
172		candidates = append(candidates,
173			candidate{dir: string(filepath.Separator) + "opt" + string(filepath.Separator) + "homebrew" + string(filepath.Separator) + "Caskroom" + string(filepath.Separator) + "entire@nightly", cask: "entire@nightly"},
174			candidate{dir: string(filepath.Separator) + "opt" + string(filepath.Separator) + "homebrew" + string(filepath.Separator) + "Caskroom" + string(filepath.Separator) + "entire", cask: "entire"},
175			candidate{dir: string(filepath.Separator) + "usr" + string(filepath.Separator) + "local" + string(filepath.Separator) + "Caskroom" + string(filepath.Separator) + "entire@nightly", cask: "entire@nightly"},
176			candidate{dir: string(filepath.Separator) + "usr" + string(filepath.Separator) + "local" + string(filepath.Separator) + "Caskroom" + string(filepath.Separator) + "entire", cask: "entire"},
177		)
178	
179		for _, candidate := range candidates {
180			for _, dir := range pathAliases(candidate.dir) {
181				if isSubpath(path, dir) {
182					return candidate.cask, true
183				}
184			}
185		}
186		return "", false
187	}
