10		"github.com/spf13/cobra"
11	)
12	
13	func execute(t *testing.T, cmd *cobra.Command, args ...string) (string, error) {
14		t.Helper()
15	
16		var stdout bytes.Buffer
17		cmd.SetOut(&stdout)
18		cmd.SetErr(&stdout)
19		cmd.SetArgs(args)
20		err := cmd.Execute()
21		return stdout.String(), err
22	}
23	
24	func TestRootUpgradeDefaultsToStable(t *testing.T) {
25		var got upgrade.Options
26		cmd := NewRootCommand(Options{
27			Version: "test-version",
28			UpgradeRunner: func(_ context.Context, opts upgrade.Options) error {
29				got = opts
30				return nil
31			},
32		})
33	
34		out, err := execute(t, cmd)
35		if err != nil {
36			t.Fatalf("execute root: %v\n%s", err, out)
37		}
38		if got.Channel != upgrade.StableChannel {
39			t.Fatalf("channel = %s, want %s", got.Channel, upgrade.StableChannel)
40		}
41		if got.ExplicitChannel {
42			t.Fatal("default stable channel should not be explicit")
43		}
44	}
45	
46	func TestRootUpgradeNightlyFlag(t *testing.T) {
47		var got upgrade.Options
48		cmd := NewRootCommand(Options{
49			Version: "test-version",
50			UpgradeRunner: func(_ context.Context, opts upgrade.Options) error {
51				got = opts
52				return nil
53			},
54		})
55	
56		out, err := execute(t, cmd, "--nightly")
57		if err != nil {
58			t.Fatalf("execute root: %v\n%s", err, out)
59		}
60		if got.Channel != upgrade.NightlyChannel {
61			t.Fatalf("channel = %s, want %s", got.Channel, upgrade.NightlyChannel)
62		}
63		if !got.ExplicitChannel {
64			t.Fatal("nightly flag did not mark channel explicit")
65		}
66	}
