	return installedChannel(install) == channel
}

func installedChannel(install Installation) Channel {
	if install.Method == MethodHomebrew {
		switch install.BrewCask {
		case "entire@nightly":
			return NightlyChannel
		case "entire":
			return StableChannel
		}
